changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Pays-Bas – Parlement', 'Membres de la Tweede Kamer (API OData ouverte) et de l''Eerste Kamer (liste officielle), en fonction et sortis depuis moins de 12 mois (catégorie NL-b)', 'nl_pep_parliament', 'PEP', 'https://opendata.tweedekamer.nl/', 'nl-pep-parliament', 'D:/test parser 2/plugins/swiftcheck-aml-nl-pep-parliament-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'API', NULL, '{"odataUrl": "https://gegevensmagazijn.tweedekamer.nl/OData/v4/2.0", "senateUrl": "https://www.eerstekamer.nl/alle_leden", "monthsAfterEnd": "12", "delayMs": "500"}', 168, 12, 'Données ouvertes de la Tweede Kamer : citer la source ; liste de l''Eerste Kamer : site officiel', 'Tweede Kamer der Staten-Generaal (opendata.tweedekamer.nl) ; Eerste Kamer der Staten-Generaal (eerstekamer.nl)', 'Environ 20 appels (13 pages de personnes). Tweede Kamer : 150 en fonction + anciens de la période (identité, naissance, genre, groupe). Eerste Kamer : les 75 membres de la liste officielle, nom complet repris de la fiche Persoon de même naissance et même nom (55 sur 75 à ce jour) ; les anciens sénateurs ne sont pas repris, la source ne donne pas leur chambre. Les décédés sont écartés. Un historique plus long : monthsAfterEnd plus grand.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Tous les membres de la Tweede Kamer en fonction et sortis depuis moins de 12 mois, avec naissance, genre, groupe et dates de mandat.', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'NL-b' AND f.label IN ('Membre de la Tweede Kamer', 'Ancien membre de la Tweede Kamer') AND p.dataset_name = 'nl_pep_parliament';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Les 75 sénateurs en fonction de la liste officielle, avec groupe, naissance et début de mandat (calculé depuis l''ancienneté en jours).', 'Anciens sénateurs non repris (la source ne donne pas leur chambre) ; nom complet seulement quand la fiche Persoon correspond.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'NL-b' AND f.label = 'Membre de l''Eerste Kamer' AND p.dataset_name = 'nl_pep_parliament';

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Pays-Bas – Hautes institutions', 'Membres de la Raad van State, de la Hoge Raad et de l''Algemene Rekenkamer, d''après les pages officielles (catégories NL-d et NL-e)', 'nl_pep_institutions', 'PEP', 'https://www.raadvanstate.nl/', 'nl-pep-institutions', 'D:/test parser 2/plugins/swiftcheck-aml-nl-pep-institutions-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"sources": "raad_van_state|Raad van State|https://www.raadvanstate.nl/overrvs/organisatie/leden-staatsraden/;hoge_raad|Hoge Raad|https://www.hogeraad.nl/hoge-raad/kamers/;algemene_rekenkamer|Algemene Rekenkamer|https://www.rekenkamer.nl/over-de-algemene-rekenkamer/organisatie/college", "delayMs": "1500"}', 168, 12, 'Sites officiels des institutions : citer la source', 'Raad van State, Hoge Raad, Algemene Rekenkamer', 'Un extracteur par site. Raad van State : prénoms lus entre parenthèses ; Hoge Raad : initiales seulement ; Rekenkamer : trois membres du collège. Ni dates ni naissance : seuls les membres en fonction sont nommés. De Nederlandsche Bank (403) non couverte, non contournée.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Membres de la Raad van State et de la Hoge Raad en fonction (vice-président, président, staatsraden, raadsheren).', 'Hoge Raad : initiales seulement ; Centrale Raad van Beroep et College van Beroep voor het bedrijfsleven non couverts ; pas de dates ni de naissance.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'NL-d' AND f.label = 'Membre de la Raad van State ou de la Hoge Raad' AND p.dataset_name = 'nl_pep_institutions';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les trois membres du collège de l''Algemene Rekenkamer (président compris).', 'Pas de dates ni de naissance.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'NL-e' AND f.label = 'Membre du collège de l''Algemene Rekenkamer' AND p.dataset_name = 'nl_pep_institutions';
